          + ' 0-17.709176-14.305882-32.015059-32.015059-32.015059h-213.323294C200.432941 90.563765 90.352941 200.643765 90.352941 335.902118'
          + 'v341.323294c0 135.258353 110.08 245.338353 245.338353 245.338353h341.323294c135.258353 0 245.338353-110.08 245.338353-245.338353'
          + 'v-213.323294c0-17.709176-14.305882-32.015059-32.015059-32.015059l-0.210823-0.210824z'
